{"arxiv_id": "1901.09890v1", "title": "Few-shot Learning with Meta Metric Learners", "normalized_lane": "metalearning_fewshot", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Add a regime-librarian retrieval layer for new-regime prediction: retrieve top-s most related historical team-seasons via per-season matching networks, then adapt with a meta-metric-learner at K in {2,4} observed games, falling back to the league-average prior when no season is better than chance.", "gate": "ADOPT iff the retrieval+meta-metric-learner beats plain Matching Network by >=3pp accuracy on new-regime win prediction at K in {2,4} (2023-2025 test regimes), AND the random-auxiliary ablation shows no gain (proving retrieval, not just extra data, drives it).", "owner": "Hermes", "bucket": "MODEL", "effort": "medium", "depends_on": []}
{"arxiv_id": "1902.04256", "title": "A Theory of Selective Prediction", "normalized_lane": "abstention", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Replace week-to-week re-tuning of publish gates with a pre-committed season-start gating strictness schedule (full-card vs reduced-card weeks) chosen on historical variance structure; use the adaptive-vs-committed backtest gap as an overfitting diagnostic.", "gate": "ADAPT accepted if the backtest shows the pre-committed gating schedule's error is within a small factor of any adaptive alternative's (confirming the theory's practical bite: stop over-tuning weekly gates); rejected if adaptive scheduling wins by a large, stable margin.", "owner": "Mimo", "bucket": "DECIDE", "effort": "small", "depends_on": []}
