{"arxiv_id": "1905.07886", "title": "Conformal Prediction Interval Estimations with an Application to Day-Ahead and Intraday Power Markets", "normalized_lane": "calibration", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Add a normalized-nonconformity interval option ([yhat - sigmahat*qhat, yhat + sigmahat*qhat] with a per-game dispersion estimate) and a rolling-window (not random-split) calibration design to GSE's interval layer, with a per-market path-selection protocol ({plain CP, NCP} x point predictor) picking the winner per market.", "gate": "ADOPT NCP if it achieves nominal coverage within 2pp AND mean width <= plain-CP width on the 2025 holdout; KEEP the path-selection protocol regardless (it is process, not a claim); REJECT the random-split calibration design outright -- never use it on ordered NFL data.", "owner": "Mimo", "bucket": "MODEL", "effort": "medium", "depends_on": []}
{"arxiv_id": "1905.09561v1", "title": "Binary Classification with Bounded Abstention Rate", "normalized_lane": "abstention", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Ship a weekly board volume governor: fix a publish skip budget delta (e.g. 0.25), compute the delta-quantile of calibrated |p_cover - 0.5| ambiguity on the unlabeled slate, and skip games below it -- deployable before kickoff with no labels needed.", "gate": "ADOPT if at delta=0.2 the published set beats publish-all by >=2.0 pp hit rate (Wilcoxon p<0.05 over 18 weeks) AND the achieved skip rate is within +/-3 pp of delta every week (rate-control check); otherwise REJECT.", "owner": "Hermes", "bucket": "DECIDE", "effort": "small", "depends_on": []}
{"arxiv_id": "1905.10964v2", "title": "Combating Label Noise in Deep Learning Using Abstention", "normalized_lane": "abstention", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Train a DAC-style variant of the GSE pick model with a k+1 abstention head on noisy-ish targets, drop the games it abstains on at the best clean-validation checkpoint, retrain the production model on the cleaner set, and reuse the abstained set as an interpretable 'unreliable game' detector for the write-up pipeline.", "gate": "ADAPT if the post-cleaning retrained model beats the all-data baseline on test Brier by >=0.003 with the abstained fraction <=25% of training games; reject if the gain is <0.003 or cleaning removes >40% of games (sample destruction).", "owner": "Hermes", "bucket": "DECIDE", "effort": "medium", "depends_on": []}
{"arxiv_id": "1905.11481v2", "title": "AI Feynman: a Physics-Inspired Method for Symbolic Regression", "normalized_lane": "symreg_equation_discovery", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Build an AI-Feynman-lite front end to PySR: fit a small MLP to points-per-drive, probe additive separability across feature groups (offense vs defense vs context) via Delta_sep, run PySR per group and recombine, with a scale-analysis module normalizing by pace.", "gate": "ADOPT the separability front-end if it yields >=5% held-out RMSE improvement over flat PySR on the 2024-2025 test window with no more than 20% more total nodes; REJECT if separability never fires or the recombined equation underperforms flat search.", "owner": "Motif-lab", "bucket": "INVENT", "effort": "medium", "depends_on": []}
