{"arxiv_id": "2407.08508", "title": "PEP: Tackle Value as Prevented Expected Points", "normalized_lane": "tracking", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Score tackles as prevented expected points via the counterfactual-removal GAMLSS, and close the authors' gap by scoring missed tackles with the inverted counterfactual on charted missed-tackle events to build a net tackling metric (PEP_made − PEP_missed), splitting the mixed model by run/pass to remove CB catch-and-tackle bias, as an input to defensive player ratings.", "gate": "ADAPT if: (a) RF out-of-sample EOPY predictions achieve MAE ≤ 3.5 yards on held-out weeks (paper: 3.13), and (b) the tackler random intercept predicts second-half tackles per snap with out-of-sample R² ≥ 0.05 above the raw-tackle-rate baseline.", "owner": "Motif-lab", "bucket": "INGEST", "effort": "medium", "depends_on": []}
{"arxiv_id": "2407.11501v1", "title": "Diff-MTS: Temporal-Augmented Conditional Diffusion for Multivariate Time Series", "normalized_lane": "synthetic_data", "verdict": "ADAPT", "doctrine_tag": "INFRA", "improvement": "Adopt Diff-MTS as GSE's primary trajectory/panel generator with matchup-graph conditioning (week's opponent-strength/home-away graph embedding in the condition vector) and apply the Ada-MMD regularizer to the cross-team correlation structure of the denoised output, not just noise distributions.", "gate": "ADOPT Diff-MTS as the lane's primary trajectory generator if: (a) discriminative score <0.75 on NFL data, AND (b) predictive-score RMSE within 15% of real-trained on held-out seasons, AND (c) condition consistency ≥80%.", "owner": "Motif-lab", "bucket": "INGEST", "effort": "large", "depends_on": []}
{"arxiv_id": "2407.13438", "title": "The Madness of Multiple Entries in March Madness", "normalized_lane": "props_dfs", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Replace max-EV 150-entry GPP construction with the paper's expected-maximum-score (EMS) portfolio optimizer using SAA/PROP+ greedy heuristics, extended to field-aware EMS that maximizes P(best entry beats the field's best entry) against K synthetic sharp entries so portfolios gain contrarian leverage instead of raw EMS alone.", "gate": "Adopt the EMS portfolio optimizer if on 2024 backtests the G-SAA or PROP+ 150-entry portfolio beats the 150×-max-EV baseline on simulated EMS by ≥5.0 points AND on realized best-entry finish percentile by ≥5 percentile points across ≥10 slates; reject if the SAA MILP doesn't solve within 30 minutes per slate.", "owner": "Hermes", "bucket": "MODEL", "effort": "medium", "depends_on": []}
{"arxiv_id": "2407.15900", "title": "Improving Probabilistic Forecasts of Extreme Wind Speeds by Training Statistical Post-Processing Models with Weighted Scoring Rules", "normalized_lane": "weather", "verdict": "ADAPT", "doctrine_tag": "SITUATIONAL", "improvement": "Train GSE's weather post-processing models with tail-weighted twCRPS plus pooled EMOS-style combination, but set the weight threshold at value-weighted points (totals near key numbers, regions of historically largest GSE edge) rather than climatological quantiles, so the tail focus lands where the money is.", "gate": "ADOPT the twCRPS + pooling pipeline if the 90th-percentile twCRPS skill gain is ≥1% with body degradation ≤0.5% on the 2024–2025 test; REJECT pure-twCRPS training (no pooling) if body CRPS degrades >1%.", "owner": "Mimo", "bucket": "INGEST", "effort": "medium", "depends_on": []}
{"arxiv_id": "2407.17832", "title": "Regularized Adjusted Plus-Minus Models for Evaluating and Scouting Football (Soccer) Players using Possession Sequences", "normalized_lane": "props_dfs", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Rebuild GSE's drive-level NFL player ratings as group-lasso regularized plus-minus on possession segments (position-group penalties, separating on-ball and off-ball contributions) with expected-points value targets instead of binary indicators, using the train-ratings→predict-games validity protocol to turn player ratings into game predictions.", "gate": "Rebuild on one NFL season of drive data: require group lasso ≥ ridge on Brier score for held-out games, and both significantly better than an ELO-only baseline at 10% (paired t-test); improvement experiment success = Brier-score improvement ≥ 5% over the goal-indicator version.", "owner": "Motif-lab", "bucket": "MODEL", "effort": "medium", "depends_on": []}
