{"arxiv_id": "2409.05144v3", "title": "QuantFactor REINFORCE: Mining Steady Formulaic Alpha Factors with Variance-bounded REINFORCE", "normalized_lane": "signal_discovery_alpha_mining", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Mine formulaic NFL alphas with variance-bounded REINFORCE where candidate formulas are shaped by forward-walk information ratio (worst-fold expanding-window IC as the reward, not training-window IR) and co-mine small factor sets jointly with a diversity bonus instead of mining single factors one by one.", "gate": "ADAPT→build if QFR-miner beats GP by ≥ 20% relative RankIC on the 2022–2025 test block with ≤ the same GPU budget AND the top-10 mined factors each pass a White's-reality-check gate (p < 0.05) on the test block.", "owner": "Motif-lab", "bucket": "INGEST", "effort": "large", "depends_on": []}
{"arxiv_id": "2409.05714v2", "title": "Analyzing and Forecasting Success in the Men's Ice Hockey World (Junior) Championships Using a Dynamic Ranking Model", "normalized_lane": "team_ratings", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Adopt the score-driven dynamic Plackett-Luce model for GSE's pre-season standings forecasts, replacing modal-rank evaluation with expected-rank metrics (E[rank_i], P(rank_i ≤ k) from 10k simulated draws per season) so model selection uses a defensible rank-accuracy metric instead of unreliable modal-rank MAE.", "gate": "Adopt the score-driven dynamic PL for GSE's pre-season standings model if, on 2015–2025 rolling forecasts, the AIC-final penalized model beats the static model on average log-likelihood by ≥0.05/season AND achieves P(division winner) ≥ market-implied baseline within 0.03.", "owner": "Mimo", "bucket": "INGEST", "effort": "medium", "depends_on": []}
{"arxiv_id": "2409.08172v4", "title": "A Bayesian framework for analyzing alleged cheating in sports through hidden codes", "normalized_lane": "bayesian", "verdict": "ADAPT", "doctrine_tag": "PROPRIETARY_EDGE", "improvement": "Deploy the likelihood-ratio anomaly detector as GSE's game-integrity monitor, extended from fixed per-case priors to a hierarchical model over referee crews with partial pooling so signal probability and honest baselines are learned jointly across crews, including crews with little history.", "gate": "ADOPT the monitor if the LR detector catches at least as many labeled anomalous games as the z-score baseline with no more than 1/2 the false-positive rate on the 2025 weeks 1–3 window; REJECT otherwise.", "owner": "Mimo", "bucket": "MODEL", "effort": "medium", "depends_on": []}
